-- Phase 5.8 idempotent scheduling, automation progression, throttling and Resend event handling.
create or replace function public.marketing_next_allowed_at(p_restaurant_id uuid,p_desired timestamptz) returns timestamptz language plpgsql stable security definer set search_path='' as $$declare v_tz text;v_start time;v_end time;v_local timestamp;v_time time;v_target timestamp;begin select coalesce(timezone,'Europe/London'),coalesce(quiet_hours_start,'21:00'),coalesce(quiet_hours_end,'08:00') into v_tz,v_start,v_end from public.restaurant_marketing_settings where restaurant_id=p_restaurant_id;v_tz:=coalesce(v_tz,'Europe/London');v_start:=coalesce(v_start,'21:00');v_end:=coalesce(v_end,'08:00');v_local:=p_desired at time zone v_tz;v_time:=v_local::time;if v_start=v_end then return p_desired;end if;if v_start<v_end and v_time>=v_start and v_time<v_end then v_target:=v_local::date+v_end;elsif v_start>v_end and(v_time>=v_start or v_time<v_end) then if v_time>=v_start then v_target:=v_local::date+1+v_end;else v_target:=v_local::date+v_end;end if;else return p_desired;end if;return v_target at time zone v_tz;end$$;
create or replace function public.marketing_segment_audience(p_restaurant_id uuid,p_segment_key text,p_custom_segment_id uuid default null) returns table(customer_user_id uuid,email text,first_name text,last_name text) language plpgsql stable security definer set search_path='' as $$declare v_filter jsonb:='{}';v_high integer;v_low integer;v_ref integer;begin if auth.role()<>'service_role' and not public.is_restaurant_member(p_restaurant_id) and not public.is_platform_admin() then raise exception 'Restaurant access denied' using errcode='42501';end if;select coalesce((select high_spender_pence from public.restaurant_marketing_settings where restaurant_id=p_restaurant_id),10000),coalesce((select low_spender_pence from public.restaurant_marketing_settings where restaurant_id=p_restaurant_id),3000),coalesce((select referral_champion_threshold from public.restaurant_marketing_settings where restaurant_id=p_restaurant_id),3) into v_high,v_low,v_ref;if p_custom_segment_id is not null then select filter_config into v_filter from public.restaurant_customer_segments where id=p_custom_segment_id and restaurant_id=p_restaurant_id and is_active;if not found then return;end if;end if;return query with base as(select o.customer_user_id,min(o.created_at) first_order_date,max(o.created_at) last_order_date,count(*)::int total_orders,coalesce(sum(o.total_pence),0)::bigint spend from public.orders o where o.restaurant_id=p_restaurant_id and o.customer_user_id is not null and o.payment_status='paid' and o.order_status<>'rejected' group by o.customer_user_id),e as(select b.*,u.email,cp.first_name,cp.last_name,cp.date_of_birth,vm.current_tier_id,floor(extract(epoch from(now()-b.last_order_date))/86400)::int inactive,(select count(*)::int from public.customer_referrals r where r.restaurant_id=p_restaurant_id and r.referrer_user_id=b.customer_user_id and r.status in('qualified','rewarded')) refs,exists(select 1 from public.customer_reward_issuances ri where ri.restaurant_id=p_restaurant_id and ri.customer_user_id=b.customer_user_id and ri.status in('available','issued') and(ri.expires_at is null or ri.expires_at>now())) reward_available,exists(select 1 from public.customer_reward_issuances ri where ri.restaurant_id=p_restaurant_id and ri.customer_user_id=b.customer_user_id and ri.status in('available','issued') and ri.created_at<now()-interval '14 days' and(ri.expires_at is null or ri.expires_at>now())) abandoned_reward,exists(select 1 from public.customer_stamp_cards sc join public.restaurant_stamp_programs sp on sp.id=sc.program_id where sc.restaurant_id=p_restaurant_id and sc.customer_user_id=b.customer_user_id and sc.is_active and sp.is_active and sc.current_stamps=greatest(sp.stamps_required-1,0)) one_stamp,exists(select 1 from public.customer_challenge_progress ccp where ccp.restaurant_id=p_restaurant_id and ccp.customer_user_id=b.customer_user_id) challenge from base b left join auth.users u on u.id=b.customer_user_id left join public.customer_profiles cp on cp.user_id=b.customer_user_id left join public.customer_vip_memberships vm on vm.restaurant_id=p_restaurant_id and vm.customer_user_id=b.customer_user_id),f as(select e.*,jsonb_build_object('lifetime_spend_pence',spend,'total_orders',total_orders,'days_since_last_order',inactive,'vip_tier_id',current_tier_id,'birthday_month',extract(month from date_of_birth)::int,'has_reward_available',reward_available,'has_one_stamp_remaining',one_stamp,'has_challenge_progress',challenge,'qualified_referrals',refs) metrics from e) select f.customer_user_id,f.email,f.first_name,f.last_name from f where(p_custom_segment_id is not null and public.marketing_segment_filter_matches(f.metrics,v_filter)) or(p_custom_segment_id is null and(coalesce(p_segment_key,'all') in('','all') or(p_segment_key='new_customers' and total_orders=1 and first_order_date>=now()-interval '30 days') or(p_segment_key='returning_customers' and total_orders>=2) or(p_segment_key='vip_customers' and current_tier_id is not null) or(p_segment_key='high_spenders' and spend>=v_high) or(p_segment_key='low_spenders' and spend<=v_low) or(p_segment_key='inactive_30_days' and inactive between 30 and 59) or(p_segment_key='inactive_60_days' and inactive between 60 and 89) or(p_segment_key='inactive_90_plus_days' and inactive>=90) or(p_segment_key='birthday_this_month' and extract(month from date_of_birth)=extract(month from current_date)) or(p_segment_key='reward_available' and reward_available) or(p_segment_key='one_stamp_remaining' and one_stamp) or(p_segment_key='referral_champions' and refs>=v_ref) or(p_segment_key='challenge_participants' and challenge) or(p_segment_key='abandoned_rewards' and abandoned_reward)));end$$;
create or replace function public.marketing_customer_filter_metrics(p_restaurant_id uuid,p_customer_user_id uuid) returns jsonb language sql stable security definer set search_path='' as $$with o as(select count(*)::int orders,coalesce(sum(total_pence),0)::bigint spend,max(created_at) last_order from public.orders where restaurant_id=p_restaurant_id and customer_user_id=p_customer_user_id and payment_status='paid' and order_status<>'rejected') select jsonb_build_object('total_orders',o.orders,'lifetime_spend_pence',o.spend,'days_since_last_order',case when o.last_order is null then null else floor(extract(epoch from(now()-o.last_order))/86400)::int end,'has_reward_available',exists(select 1 from public.customer_reward_issuances ri where ri.restaurant_id=p_restaurant_id and ri.customer_user_id=p_customer_user_id and ri.status in('available','issued') and(ri.expires_at is null or ri.expires_at>now())),'has_one_stamp_remaining',exists(select 1 from public.customer_stamp_cards sc join public.restaurant_stamp_programs sp on sp.id=sc.program_id where sc.restaurant_id=p_restaurant_id and sc.customer_user_id=p_customer_user_id and sc.is_active and sp.is_active and sc.current_stamps=greatest(sp.stamps_required-1,0)),'has_challenge_progress',exists(select 1 from public.customer_challenge_progress c where c.restaurant_id=p_restaurant_id and c.customer_user_id=p_customer_user_id),'qualified_referrals',(select count(*) from public.customer_referrals r where r.restaurant_id=p_restaurant_id and r.referrer_user_id=p_customer_user_id and r.status in('qualified','rewarded'))) from o$$;
create or replace function public.marketing_channel_allowed(p_restaurant_id uuid,p_customer_user_id uuid,p_channel text,p_category text default 'marketing') returns boolean language plpgsql stable security definer set search_path='' as $$declare gp public.customer_marketing_preferences%rowtype;rp public.customer_restaurant_marketing_preferences%rowtype;begin select * into gp from public.customer_marketing_preferences where customer_user_id=p_customer_user_id;select * into rp from public.customer_restaurant_marketing_preferences where restaurant_id=p_restaurant_id and customer_user_id=p_customer_user_id;if coalesce(gp.global_opt_out,false) or coalesce(rp.restaurant_opt_out,false) then return false;end if;if exists(select 1 from public.restaurant_marketing_suppressions s where(s.restaurant_id is null or s.restaurant_id=p_restaurant_id) and(s.customer_user_id=p_customer_user_id or lower(s.email)=lower((select email from auth.users where id=p_customer_user_id))) and s.channel=p_channel and(s.expires_at is null or s.expires_at>now())) then return false;end if;if p_channel='email' then return coalesce(gp.marketing_emails,false) and coalesce(rp.marketing_emails,true);end if;if p_channel='push' then return false;end if;if p_category='loyalty' then return coalesce(gp.loyalty_notifications,true) and coalesce(rp.loyalty_notifications,true);elsif p_category='referral' then return coalesce(gp.referral_notifications,true) and coalesce(rp.referral_notifications,true);elsif p_category='birthday' then return coalesce(gp.birthday_notifications,true) and coalesce(rp.birthday_notifications,true);else return coalesce(gp.promotional_notifications,false) and coalesce(rp.promotional_notifications,true);end if;end$$;
create or replace function public.marketing_enqueue_campaign(p_campaign_id uuid,p_scheduled_for timestamptz) returns uuid language plpgsql security definer set search_path='' as $$declare c public.restaurant_marketing_campaigns%rowtype;r_id uuid;v_total int:=0;v_queued int:=0;v_supp int:=0;a record;ch text;v_allowed boolean;v_available timestamptz;begin if auth.role()<>'service_role' then raise exception 'Service role required' using errcode='42501';end if;select * into c from public.restaurant_marketing_campaigns where id=p_campaign_id for update;if c.id is null then raise exception 'Campaign not found';end if;insert into public.restaurant_marketing_campaign_runs(campaign_id,restaurant_id,scheduled_for,status,started_at) values(c.id,c.restaurant_id,p_scheduled_for,'processing',now()) on conflict(campaign_id,scheduled_for) do update set status=case when restaurant_marketing_campaign_runs.status='failed' then 'processing' else restaurant_marketing_campaign_runs.status end returning id into r_id;if exists(select 1 from public.restaurant_marketing_campaign_runs where id=r_id and status='completed') then return r_id;end if;v_available:=public.marketing_next_allowed_at(c.restaurant_id,now());for a in select * from public.marketing_segment_audience(c.restaurant_id,c.segment_key,c.custom_segment_id) loop v_total:=v_total+1;foreach ch in array c.channels loop v_allowed:=public.marketing_channel_allowed(c.restaurant_id,a.customer_user_id,ch,'marketing');insert into public.restaurant_marketing_deliveries(restaurant_id,campaign_id,campaign_run_id,customer_user_id,channel,recipient_email,subject,preview_text,html_content,text_content,cta_label,cta_url,image_url,status,available_at,dedupe_key,metadata) values(c.restaurant_id,c.id,r_id,a.customer_user_id,ch,a.email,c.subject,c.preview_text,c.html_content,c.text_content,c.cta_label,c.cta_url,c.image_url,case when v_allowed then 'queued' else 'suppressed' end,v_available,'campaign:'||r_id||':'||a.customer_user_id||':'||ch,jsonb_build_object('first_name',a.first_name,'last_name',a.last_name,'promotion_id',c.promotion_id,'reward_catalogue_id',c.reward_catalogue_id)) on conflict(dedupe_key) do nothing;if found then if v_allowed then v_queued:=v_queued+1;else v_supp:=v_supp+1;end if;end if;end loop;end loop;update public.restaurant_marketing_campaign_runs set status='completed',audience_count=v_total,queued_count=v_queued,suppression_count=v_supp,completed_at=now() where id=r_id;return r_id;end$$;
create or replace function public.marketing_process_due_campaigns(p_limit integer default 25) returns jsonb language plpgsql security definer set search_path='' as $$declare c record;v_count int:=0;v_next timestamptz;begin if auth.role()<>'service_role' then raise exception 'Service role required' using errcode='42501';end if;for c in select * from public.restaurant_marketing_campaigns where status in('scheduled','active') and next_run_at is not null and next_run_at<=now() and coalesce(starts_at,next_run_at)<=now() and(ends_at is null or ends_at>now()) order by next_run_at for update skip locked limit least(greatest(p_limit,1),100) loop perform public.marketing_enqueue_campaign(c.id,c.next_run_at);v_count:=v_count+1;if c.campaign_type='recurring' then v_next:=case c.recurrence_unit when 'week' then c.next_run_at+make_interval(weeks=>coalesce(c.recurrence_interval,1)) when 'month' then c.next_run_at+make_interval(months=>coalesce(c.recurrence_interval,1)) else c.next_run_at+make_interval(days=>coalesce(c.recurrence_interval,1)) end;update public.restaurant_marketing_campaigns set status='active',last_run_at=now(),next_run_at=v_next,updated_at=now() where id=c.id;else update public.restaurant_marketing_campaigns set status='completed',last_run_at=now(),next_run_at=null,updated_at=now() where id=c.id;end if;end loop;return jsonb_build_object('processed',v_count);end$$;
create or replace function public.marketing_process_automation_triggers(p_limit integer default 1000) returns jsonb language plpgsql security definer set search_path='' as $$declare a record;c record;v_key text;v_count int:=0;v_seg text;begin if auth.role()<>'service_role' then raise exception 'Service role required' using errcode='42501';end if;for a in select * from public.restaurant_marketing_automations where status='active' order by last_evaluated_at nulls first loop v_seg:=coalesce(a.trigger_config->>'segment_key',case a.trigger_type when 'welcome' then 'new_customers' when 'win_back' then 'inactive_30_days' when 'reward_reminder' then 'reward_available' when 'birthday' then 'birthday_this_month' when 'vip_upgrade' then 'vip_customers' when 'referral_reminder' then 'referral_champions' when 'challenge_reminder' then 'challenge_participants' when 'one_stamp_left' then 'one_stamp_remaining' when 'inactive' then 'inactive_60_days' else 'all' end);for c in select * from public.marketing_segment_audience(a.restaurant_id,v_seg,null) limit least(greatest(p_limit-v_count,0),1000) loop v_key:=floor(extract(epoch from now())/(a.cooldown_days*86400))::bigint::text;insert into public.restaurant_marketing_automation_runs(automation_id,restaurant_id,customer_user_id,trigger_key,status,current_position,next_action_at) values(a.id,a.restaurant_id,c.customer_user_id,v_key,'running',1,now()) on conflict do nothing;if found then v_count:=v_count+1;end if;exit when v_count>=p_limit;end loop;update public.restaurant_marketing_automations set last_evaluated_at=now() where id=a.id;exit when v_count>=p_limit;end loop;return jsonb_build_object('created_runs',v_count);end$$;
create or replace function public.marketing_process_automation_steps(p_limit integer default 250) returns jsonb language plpgsql security definer set search_path='' as $$declare r record;a public.restaurant_marketing_automations%rowtype;s public.restaurant_marketing_automation_steps%rowtype;m jsonb;v_match boolean;ch text;v_email text;v_allowed boolean;v_category text;v_count int:=0;v_next int;begin if auth.role()<>'service_role' then raise exception 'Service role required' using errcode='42501';end if;for r in select * from public.restaurant_marketing_automation_runs where status in('running','waiting') and next_action_at<=now() order by next_action_at for update skip locked limit least(greatest(p_limit,1),1000) loop select * into a from public.restaurant_marketing_automations where id=r.automation_id;if a.id is null or a.status<>'active' then update public.restaurant_marketing_automation_runs set status='exited',completed_at=now(),updated_at=now() where id=r.id;continue;end if;m:=public.marketing_customer_filter_metrics(r.restaurant_id,r.customer_user_id);if a.exit_conditions<>'{}'::jsonb and public.marketing_segment_filter_matches(m,a.exit_conditions) then update public.restaurant_marketing_automation_runs set status='exited',completed_at=now(),updated_at=now() where id=r.id;v_count:=v_count+1;continue;end if;select * into s from public.restaurant_marketing_automation_steps where automation_id=r.automation_id and position=r.current_position;if s.id is null then update public.restaurant_marketing_automation_runs set status='completed',completed_at=now(),updated_at=now() where id=r.id;v_count:=v_count+1;continue;end if;if s.step_type='exit' then update public.restaurant_marketing_automation_runs set status='completed',completed_at=now(),updated_at=now() where id=r.id;elsif s.step_type='delay' then if r.step_started_at is null then update public.restaurant_marketing_automation_runs set status='waiting',step_started_at=now(),next_action_at=now()+make_interval(mins=>coalesce(s.delay_minutes,0)),updated_at=now() where id=r.id;else update public.restaurant_marketing_automation_runs set status='running',current_position=r.current_position+1,step_started_at=null,next_action_at=now(),updated_at=now() where id=r.id;end if;elsif s.step_type='condition' then v_match:=public.marketing_segment_filter_matches(m,s.condition_config);v_next:=case when v_match then coalesce(s.true_next_position,r.current_position+1) else coalesce(s.false_next_position,r.current_position+1) end;update public.restaurant_marketing_automation_runs set current_position=v_next,status='running',step_started_at=null,next_action_at=now(),updated_at=now() where id=r.id;elsif s.step_type='send' then select email into v_email from auth.users where id=r.customer_user_id;v_category:=case a.trigger_type when 'birthday' then 'birthday' when 'referral_reminder' then 'referral' when 'challenge_reminder' then 'loyalty' when 'one_stamp_left' then 'loyalty' when 'reward_reminder' then 'loyalty' when 'reward_expiring' then 'loyalty' else 'marketing' end;foreach ch in array s.channels loop v_allowed:=public.marketing_channel_allowed(r.restaurant_id,r.customer_user_id,ch,v_category);insert into public.restaurant_marketing_deliveries(restaurant_id,automation_id,automation_run_id,automation_step_id,customer_user_id,channel,recipient_email,subject,preview_text,html_content,text_content,cta_label,cta_url,image_url,status,available_at,dedupe_key,metadata) values(r.restaurant_id,a.id,r.id,s.id,r.customer_user_id,ch,v_email,s.subject,s.preview_text,s.html_content,s.text_content,s.cta_label,s.cta_url,s.image_url,case when v_allowed then 'queued' else 'suppressed' end,public.marketing_next_allowed_at(r.restaurant_id,now()),'automation:'||r.id||':'||s.id||':'||ch,jsonb_build_object('trigger_type',a.trigger_type,'promotion_id',s.promotion_id,'reward_catalogue_id',s.reward_catalogue_id)) on conflict(dedupe_key) do nothing;end loop;update public.restaurant_marketing_automation_runs set current_position=r.current_position+1,status='running',step_started_at=null,next_action_at=now(),updated_at=now() where id=r.id;end if;v_count:=v_count+1;end loop;return jsonb_build_object('processed_steps',v_count);end$$;
create or replace function public.marketing_claim_deliveries(p_limit integer default 100) returns setof public.restaurant_marketing_deliveries language plpgsql security definer set search_path='' as $$begin if auth.role()<>'service_role' then raise exception 'Service role required' using errcode='42501';end if;return query with eligible as(select d.id from public.restaurant_marketing_deliveries d left join public.restaurant_marketing_settings s on s.restaurant_id=d.restaurant_id where d.status in('queued','failed') and d.available_at<=now() and d.attempts<5 and(select count(*) from public.restaurant_marketing_deliveries x where x.restaurant_id=d.restaurant_id and x.channel=d.channel and x.sent_at>=date_trunc('day',now()))<case when d.channel='email' then coalesce(s.max_email_sends_per_day,5000) else coalesce(s.max_notification_sends_per_day,10000) end and(select count(*) from public.restaurant_marketing_deliveries x where x.restaurant_id=d.restaurant_id and x.customer_user_id=d.customer_user_id and x.sent_at>=date_trunc('day',now()))<coalesce(s.max_sends_per_customer_per_day,3) and(select count(*) from public.restaurant_marketing_deliveries x where x.restaurant_id=d.restaurant_id and x.sent_at>=now()-interval '1 minute')<coalesce(s.rate_limit_per_minute,250) order by d.available_at,d.created_at for update of d skip locked limit least(greatest(p_limit,1),500)),claimed as(update public.restaurant_marketing_deliveries d set status='processing',attempts=d.attempts+1,updated_at=now(),last_error=null from eligible e where d.id=e.id returning d.*)select * from claimed;end$$;
create or replace function public.marketing_complete_delivery(p_delivery_id uuid,p_provider_message_id text,p_token_hash text default null) returns boolean language plpgsql security definer set search_path='' as $$declare d public.restaurant_marketing_deliveries%rowtype;begin if auth.role()<>'service_role' then raise exception 'Service role required' using errcode='42501';end if;update public.restaurant_marketing_deliveries set status=case when channel='in_app' then 'delivered' else 'sent' end,provider_message_id=p_provider_message_id,sent_at=now(),delivered_at=case when channel='in_app' then now() else delivered_at end,updated_at=now() where id=p_delivery_id and status='processing' returning * into d;if d.id is null then return false;end if;if p_token_hash is not null and d.channel='email' then insert into public.restaurant_marketing_unsubscribe_tokens(delivery_id,restaurant_id,customer_user_id,token_hash) values(d.id,d.restaurant_id,d.customer_user_id,p_token_hash) on conflict(delivery_id) do nothing;end if;insert into public.restaurant_marketing_delivery_events(delivery_id,restaurant_id,event_type,event_at,metadata) values(d.id,d.restaurant_id,case when d.channel='in_app' then 'delivered' else 'sent' end,now(),'{}');return true;end$$;
create or replace function public.marketing_fail_delivery(p_delivery_id uuid,p_error text) returns boolean language plpgsql security definer set search_path='' as $$declare v_attempts int;begin if auth.role()<>'service_role' then raise exception 'Service role required' using errcode='42501';end if;select attempts into v_attempts from public.restaurant_marketing_deliveries where id=p_delivery_id for update;if v_attempts is null then return false;end if;update public.restaurant_marketing_deliveries set status=case when v_attempts>=5 then 'failed' else 'queued' end,last_error=left(p_error,500),failed_at=case when v_attempts>=5 then now() else failed_at end,available_at=now()+make_interval(mins=>least(60,power(2,greatest(v_attempts-1,0))::int*5)),updated_at=now() where id=p_delivery_id;return true;end$$;
create or replace function public.marketing_record_resend_event(p_provider_message_id text,p_event_type text,p_provider_event_id text,p_event_at timestamptz,p_metadata jsonb default '{}') returns boolean language plpgsql security definer set search_path='' as $$declare d public.restaurant_marketing_deliveries%rowtype;v_status text;begin if auth.role()<>'service_role' then raise exception 'Service role required' using errcode='42501';end if;select * into d from public.restaurant_marketing_deliveries where provider_message_id=p_provider_message_id;if d.id is null then return false;end if;insert into public.restaurant_marketing_delivery_events(delivery_id,restaurant_id,event_type,provider_event_id,event_at,metadata) values(d.id,d.restaurant_id,p_event_type,p_provider_event_id,coalesce(p_event_at,now()),coalesce(p_metadata,'{}')) on conflict(provider_event_id) do nothing;if not found then return true;end if;v_status:=case p_event_type when 'email.delivered' then 'delivered' when 'email.opened' then 'opened' when 'email.clicked' then 'clicked' when 'email.failed' then 'failed' when 'email.bounced' then 'failed' when 'email.complained' then 'failed' else d.status end;update public.restaurant_marketing_deliveries set status=v_status,delivered_at=case when p_event_type='email.delivered' then coalesce(p_event_at,now()) else delivered_at end,opened_at=case when p_event_type='email.opened' then coalesce(opened_at,p_event_at,now()) else opened_at end,clicked_at=case when p_event_type='email.clicked' then coalesce(clicked_at,p_event_at,now()) else clicked_at end,failed_at=case when p_event_type in('email.failed','email.bounced','email.complained') then coalesce(p_event_at,now()) else failed_at end,updated_at=now() where id=d.id;if p_event_type in('email.bounced','email.complained','email.suppressed') then insert into public.restaurant_marketing_suppressions(restaurant_id,customer_user_id,email,channel,reason,source) values(d.restaurant_id,d.customer_user_id,d.recipient_email,'email',case when p_event_type='email.complained' then 'complaint' else 'bounce' end,'resend_webhook') on conflict do nothing;end if;return true;end$$;
revoke all on function public.marketing_next_allowed_at(uuid,timestamptz),public.marketing_segment_audience(uuid,text,uuid),public.marketing_customer_filter_metrics(uuid,uuid),public.marketing_channel_allowed(uuid,uuid,text,text),public.marketing_enqueue_campaign(uuid,timestamptz),public.marketing_process_due_campaigns(integer),public.marketing_process_automation_triggers(integer),public.marketing_process_automation_steps(integer),public.marketing_claim_deliveries(integer),public.marketing_complete_delivery(uuid,text,text),public.marketing_fail_delivery(uuid,text),public.marketing_record_resend_event(text,text,text,timestamptz,jsonb) from public;
